import java.util.Scanner;

public class Main {
    public static int getGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int numerator = sc.nextInt();
        int denominator = sc.nextInt();
        int maxLimit = sc.nextInt();

        int gcdValue = getGCD(numerator, denominator);
        numerator /= gcdValue;
        denominator /= gcdValue;

        if (maxLimit >= denominator) {
            System.out.println(numerator + "/" + denominator);
        } else {
            double ratio = (double) numerator / denominator;
            double minDifference = ratio;
            int bestNum = 0;
            int bestDen = 1;

            for (int i = 1; i <= maxLimit; ++i) {
                double scaled = i * ratio;
                double floorScaled = Math.floor(scaled);
                double diff1 = Math.abs(floorScaled / i - ratio);
                double diff2 = Math.abs((floorScaled + 1) / i - ratio);

                if (minDifference > diff1 || minDifference > diff2) {
                    if (diff1 > diff2) {
                        bestNum = (int) (floorScaled + 1);
                    } else {
                        bestNum = (int) floorScaled;
                    }
                    bestDen = i;
                    minDifference = Math.min(diff1, diff2);
                }
            }
            System.out.println(bestNum + "/" + bestDen);
        }
        sc.close();
    }
}
